import{_ as e,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Filter Widgets - October CMS - 4.x","titleTemplate":false,"description":"A widget specifically made for use in a filter.","frontmatter":{"subtitle":"A widget specifically made for use in a filter."},"headers":[{"level":2,"title":"Class Definition","slug":"class-definition","link":"#class-definition","children":[]},{"level":2,"title":"Filter Widget Properties","slug":"filter-widget-properties","link":"#filter-widget-properties","children":[]},{"level":2,"title":"Filter Widget Registration","slug":"filter-widget-registration","link":"#filter-widget-registration","children":[]},{"level":2,"title":"Displaying the Filter State","slug":"displaying-the-filter-state","link":"#displaying-the-filter-state","children":[]},{"level":2,"title":"Displaying the Filter Form","slug":"displaying-the-filter-form","link":"#displaying-the-filter-form","children":[]},{"level":2,"title":"Capturing the Filter Value","slug":"capturing-the-filter-value","link":"#capturing-the-filter-value","children":[]},{"level":2,"title":"Applying the Scope to the Query","slug":"applying-the-scope-to-the-query","link":"#applying-the-scope-to-the-query","children":[]},{"level":2,"title":"Working with Inline Filters","slug":"working-with-inline-filters","link":"#working-with-inline-filters","children":[]}],"relativePath":"4.x/extend/lists/filter-widgets.md","filePath":"4.x/extend/lists/filter-widgets.md"}'),u={name:"4.x/extend/lists/filter-widgets.md"};function r(k,n,d,g,h,m){const t=a("pre-heading"),p=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"Filter Widgets",-1)),s(p),n[1]||(n[1]=i(`<p>With filter widgets you can add new scope types to the backend filters. They provide features that are common to filtering lists. Filter widgets must be registered in the <a href="./../extending.html">plugin registration file</a>.</p><p>Filter Widget classes reside inside the <strong>filterwidgets</strong> directory of the plugin directory. The inner directory name matches the name of the widget class written in lowercase. Widgets can supply assets and partials. An example form widget directory structure looks like this.</p><pre class="dir-container"><code><p>├── <code>filterwidgets</code>
|   ├── discount
|   |   ├── partials
|   |   |   └── _discount.php  <em>← Partial File</em>
|   |   |   └── _discount_form.php
|   |   └── assets
|   |       ├── js
|   |       |   └── discount.js  <em>← JavaScript File</em>
|   |       └── css
|   |           └── discount.css  <em>← StyleSheet File</em>
|   └── Discount.php  <em>← Widget Class</em></p>
</code></pre><h2 id="class-definition"><a href="#class-definition" class="header-anchor">#</a> Class Definition</h2><p>The <code>create:filterwidget</code> command generates a backend filter widget, view and basic asset files. The first argument specifies the author and plugin name. The second argument specifies the form widget class name.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:filterwidget Acme.Blog Discount
</code></pre></div><p>The filter widget classes must extend the <code>Backend\\Classes\\FilterWidgetBase</code> class. A registered widget can be used in the backend <a href="./../../element/filter-scopes.html">filter field definition</a> file. Example form widget class definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Backend<span class="token punctuation">\\</span>FilterWidgets</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>FilterWidgetBase</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Discount</span> <span class="token keyword">extends</span> <span class="token class-name">FilterWidgetBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">renderForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="filter-widget-properties"><a href="#filter-widget-properties" class="header-anchor">#</a> Filter Widget Properties</h2><p>Filter widgets may have properties that can be set using the <a href="./../../element/filter-scopes.html">filter scope configuration</a>. Simply define the configurable properties on the class and then call the <code>fillFromConfig</code> method to populate them inside the <code>init</code> method definition.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Discount</span> <span class="token keyword">extends</span> <span class="token class-name">FormWidgetBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var bool allowSearch show the search input in the dropdown
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$allowSearch</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>

    <span class="token comment">/**
     * init the widget
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">fillFromConfig</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;allowSearch&#39;</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The property values then become available to set from the <a href="./../../element/filter-scopes.html">filter scope definition</a> when using the widget.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">discount</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Discount
    <span class="token key atrule">type</span><span class="token punctuation">:</span> discount
    <span class="token key atrule">allowSearch</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h2 id="filter-widget-registration"><a href="#filter-widget-registration" class="header-anchor">#</a> Filter Widget Registration</h2><p>Plugins should register filter widgets by overriding the <code>registerFilterWidgets</code> method inside the <a href="./../extending.html">plugin registration file</a>. The method returns an array containing the widget class in the keys and widget short code as the value. Example:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerFilterWidgets</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>FilterWidgets<span class="token punctuation">\\</span>Discount</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;discount&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The short code is used when referencing the widget in the filter scope definitions and it should be a unique value to avoid conflicts with other filter fields.</p><h2 id="displaying-the-filter-state"><a href="#displaying-the-filter-state" class="header-anchor">#</a> Displaying the Filter State</h2><p>The main purpose of the filter widget is to apply a scope to the query of a model, which means capturing values from the user first. The <code>render</code> method is used to display the initial state of the filter and the <code>filterScope</code> property will contain active value along with other configured properties.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">render</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;scope&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">filterScope</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getScopeName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getLoadValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;discount&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>At a basic level the filter widget should show a label and its current state to the user. The contents are also wrapped in an anchor that is used to display the filter form.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>javascript:;<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-scope <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$value</span> <span class="token operator">?</span> <span class="token string single-quoted-string">&#39;active&#39;</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;&#39;</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-scope-name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
<span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-label<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token function">trans</span><span class="token punctuation">(</span><span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">label</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-setting<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>1<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="displaying-the-filter-form"><a href="#displaying-the-filter-form" class="header-anchor">#</a> Displaying the Filter Form</h2><p>When a user clicks on the filter label, a form is displayed so that they may specify how to apply the filter. The <code>renderForm</code> method is used to display the filter form and should correspond to a <code>_discount_form.php</code> partial.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">renderForm</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;allowSearch&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">allowSearch</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;scope&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">filterScope</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getScopeName</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getLoadValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;discount_form&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The contents should contain the form values and buttons to apply or clear the filter. A form HTML tag is not required and all inputs should belong to the <code>Filter[]</code> input array. The most common place to store the filtered value is the <code>value</code> attribute.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-box<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-facet<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>facet-item is-grow<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>select</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Filter[value]<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-control form-control-sm custom-select <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$allowSearch</span> <span class="token operator">?</span> <span class="token string single-quoted-string">&#39;&#39;</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;select-no-search&#39;</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>option</span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>1<span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;1&#39;</span> <span class="token operator">?</span> <span class="token string single-quoted-string">&#39;selected=&quot;selected&quot;&#39;</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;&#39;</span> <span class="token delimiter important">?&gt;</span></span></span><span class="token punctuation">&gt;</span></span>has a discount<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>option</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>option</span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>0<span class="token punctuation">&quot;</span></span> <span class="token attr-name"><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span> <span class="token operator">===</span> <span class="token string single-quoted-string">&#39;0&#39;</span> <span class="token operator">?</span> <span class="token string single-quoted-string">&#39;selected=&quot;selected&quot;&#39;</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;&#39;</span> <span class="token delimiter important">?&gt;</span></span></span><span class="token punctuation">&gt;</span></span>does not have a discount<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>option</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>select</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-buttons<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-sm btn-primary<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-filter-action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>apply<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Apply
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>flex-grow-1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-sm btn-secondary<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-filter-action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>clear<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
            Clear
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>The <code>$value</code> variable will contain an array of the selected values. This array will be merged with the <code>$scope</code> variable for convenience, so you can access the active value via <code>$scope-&gt;value</code>. In summary, use <code>$value</code> to check if a scope is applied and <code>$scope</code> to access the values.</p></div><h2 id="capturing-the-filter-value"><a href="#capturing-the-filter-value" class="header-anchor">#</a> Capturing the Filter Value</h2><p>The <code>getActiveValue</code> method is used to capture the filtered form values and storing them. It should return an array (or null) and use postback data for finding the values. If the <code>clearScope</code> postback value exists, it means the scope wants to be cleared. You may use the <code>hasPostValue</code> helper method to check if the value was found and is not an empty string.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getActiveValue</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;clearScope&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant">null</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">hasPostValue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant">null</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token keyword">return</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Filter&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="applying-the-scope-to-the-query"><a href="#applying-the-scope-to-the-query" class="header-anchor">#</a> Applying the Scope to the Query</h2><p>Once a filter value has been captured it can be applied to the query with the <code>applyScopeToQuery</code> method. The value can be taken from the <code>filterScope-&gt;value</code> property where the <code>value</code> name comes from the filter form values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">applyScopeToQuery</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$hasDiscount</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">filterScope</span><span class="token operator">-&gt;</span><span class="token property">value</span><span class="token punctuation">;</span>

    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$hasDiscount</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;discount&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">else</span> <span class="token punctuation">{</span>
        <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;discount&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="working-with-inline-filters"><a href="#working-with-inline-filters" class="header-anchor">#</a> Working with Inline Filters</h2><p>Inline filters are filters that can exist as part of the main filter interface, instead of displaying them as a popover form. Accordingly, inside the filter widget class the <code>renderForm</code> method is not required and only the <code>render</code> method is used to display the filter contents.</p><p>The example below shows an inline search filter with a search button. It is important to keep in mind that since the filter is inline, the input field names are shared across the main form, so the search input uses the <code>$name</code> variable, instead of the generic <code>Filter</code> name.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
    <span class="token variable">$activeValue</span> <span class="token operator">=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeValue</span> <span class="token operator">!==</span> <span class="token constant">null</span> <span class="token operator">?</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span> <span class="token punctuation">:</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">default</span><span class="token punctuation">;</span>
<span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-scope scope-inline<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-scope-name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeName</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span>
        <span class="token attr-name">placeholder</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getHeaderValue</span><span class="token punctuation">(</span><span class="token variable">$scope</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span>[value]<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token function">e</span><span class="token punctuation">(</span><span class="token variable">$activeValue</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-control form-control-sm<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-sm btn-search<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-filter-action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>apply<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>i</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>icon-search<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>i</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The next example shows an inline balloon selector control.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span>
    <span class="token variable">$activeValue</span> <span class="token operator">=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeValue</span> <span class="token operator">!==</span> <span class="token constant">null</span> <span class="token operator">?</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">value</span> <span class="token punctuation">:</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">default</span><span class="token punctuation">;</span>
<span class="token delimiter important">?&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span>
    <span class="token attr-name">data-scope-name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">scopeName</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-control</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>balloon-selector<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-selector-allow-empty</span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>filter-scope scope-inline control-balloon-selector form-control-sm<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>list-unstyled m-0<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token keyword type-casting">array</span><span class="token punctuation">)</span> <span class="token variable">$scope</span><span class="token operator">-&gt;</span><span class="token property">options</span> <span class="token keyword">as</span> <span class="token variable">$key</span> <span class="token operator">=&gt;</span> <span class="token variable">$value</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span>
                <span class="token attr-name">data-value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$key</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>small <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$key</span> <span class="token operator">===</span> <span class="token variable">$activeValue</span> <span class="token operator">?</span> <span class="token string single-quoted-string">&#39;active&#39;</span> <span class="token punctuation">:</span> <span class="token string single-quoted-string">&#39;&#39;</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
                <span class="token attr-name">data-filter-action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>apply<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
                <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$value</span> <span class="token delimiter important">?&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endforeach</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- Hidden input to store the selected filter value --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hidden<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$name</span> <span class="token delimiter important">?&gt;</span></span>[value]<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$activeValue</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,40))])}const y=e(u,[["render",r]]);export{v as __pageData,y as default};
